import random
def lru(ref, n):
    mem = []; f = 0
    for p in ref:
        if p in mem:
            mem.remove(p); mem.append(p); continue
        f += 1
        if len(mem) == n: mem.pop(0)
        mem.append(p)
    return f

def opt(ref, n):
    mem = []; f = 0
    for i, p in enumerate(ref):
        if p in mem: continue
        f += 1
        if len(mem) == n:
            far = -1; vic = None
            for m in mem:
                try: nxt = ref.index(m, i+1)
                except ValueError: nxt = float('inf')
                if nxt > far: far = nxt; vic = m
            mem.remove(vic)
        mem.append(p)
    return f

