def sim(inherit):
    prio = {'L':1, 'M':2, 'H':3}
    arrive = {'L':0, 'H':1, 'M':2}
    need = {'L':10, 'M':100, 'H':5}   # L과 H는 전 구간이 임계구역
    eff = dict(prio); lock = None; blocked = set(); done = {}; t = 0
    while len(done) < 3 and t < 1000:
        ready = [k for k in need if need[k] > 0 and arrive[k] <= t and k not in blocked]
        if not ready:
            t += 1; continue
        cur = max(ready, key=lambda k: (eff[k], -arrive[k]))
        if cur in ('L','H'):
            if lock is None: lock = cur
            elif lock != cur:
                blocked.add(cur)
                if inherit: eff[lock] = max(eff[lock], eff[cur])
                continue
        need[cur] -= 1; t += 1
        if need[cur] == 0:
            done[cur] = t
            if lock == cur:
                lock = None; eff[cur] = prio[cur]; blocked.clear()
    return done

