def safe(total, alloc, mx):
    n = len(alloc)
    avail = total - sum(alloc)
    need = [mx[i]-alloc[i] for i in range(n)]
    fin = [False]*n; work = avail; changed = True
    while changed:
        changed = False
        for i in range(n):
            if not fin[i] and need[i] <= work:
                work += alloc[i]; fin[i] = True; changed = True
    return all(fin)

